@Override
    public boolean doHurtTarget(@NotNull Entity entityIn) {
        if (this.getAnimation() != ANIMATION_BITE) {
            this.setAnimation(ANIMATION_BITE);
            this.playSound(this.getScale() > 3 ? IafSoundRegistry.DEATHWORM_GIANT_ATTACK : IafSoundRegistry.DEATHWORM_ATTACK, 1, 1);
        }
        if (this.getRandom().nextInt(3) == 0 && this.getScale() > 1 && this.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
            if (!MinecraftForge.EVENT_BUS.post(new GenericGriefEvent(this, entityIn.getX(), entityIn.getY(), entityIn.getZ()))) {
                BlockLaunchExplosion explosion = new BlockLaunchExplosion(level, this, entityIn.getX(), entityIn.getY(), entityIn.getZ(), this.getScale());
                explosion.explode();
                explosion.finalizeExplosion(true);
            }
        }
        return false;
    }

@Override
    public boolean canUse() {
        if (this.targetChance > 0 && this.mob.getRandom().nextInt(this.targetChance) != 0) {
            return false;
        }
        List<ItemEntity> list = this.mob.level.getEntitiesOfClass(ItemEntity.class,
            this.getTargetableArea(this.getFollowDistance()), this.targetEntitySelector);
        if (list.isEmpty()) {
            return false;
        } else {
            list.sort(this.theNearestAttackableTargetSorter);
            this.targetEntity = list.get(0);
            return true;
        }
    }

protected AABB getTargetableArea(double targetDistance) {
        return this.mob.getBoundingBox().inflate(targetDistance, 4.0D, targetDistance);
    }

@Override
    public void start() {
        this.mob.getNavigation().moveTo(this.targetEntity.getX(), this.targetEntity.getY(),
            this.targetEntity.getZ(), 1);
        super.start();
    }

@Override
    public boolean canContinueToUse() {
        Entity itemTarget = targetEntity;

        if (itemTarget == null) {
            return false;
        } else if (!itemTarget.isAlive()) {
            return false;
        } else {
            Team team = this.mob.getTeam();
            Team team1 = itemTarget.getTeam();
            if (team != null && team1 == team) {
                return false;
            } else {
                double d0 = this.getFollowDistance();
                return !(this.mob.distanceToSqr(itemTarget) > d0 * d0);
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (this.targetEntity == null || !this.targetEntity.isAlive()) {
            this.stop();
        } else if (this.mob.distanceToSqr(this.targetEntity) < 1) {
            EntityDeathWorm deathWorm = (EntityDeathWorm) this.mob;
            this.targetEntity.getItem().shrink(1);
            this.mob.playSound(SoundEvents.GENERIC_EAT, 1, 1);
            deathWorm.setAnimation(EntityDeathWorm.ANIMATION_BITE);
            Player thrower = null;
            if (this.targetEntity.getThrower() != null)
                thrower = this.targetEntity.level.getPlayerByUUID(this.targetEntity.getThrower());
            deathWorm.setExplosive(true, thrower);
            stop();
        }

        if (worm.getNavigation().isDone()) {
            worm.getNavigation().moveTo(targetEntity, 1.0F);
        }

    }

@Override
    public void aiStep() {
        super.aiStep();
        yBodyRot = getYRot();

        LivingEntity attackTarget = this.getTarget();
        if (singCooldown > 0) {
            singCooldown--;
            this.setSinging(false);
        }
        if (!level.isClientSide && attackTarget == null && !this.isAgressive()) {
            this.setSinging(true);
        }
        if (this.getAnimation() == ANIMATION_BITE && attackTarget != null && this.distanceToSqr(attackTarget) < 7D && this.getAnimationTick() == 5) {
            attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
        }
        if (this.getAnimation() == ANIMATION_PULL && attackTarget != null && this.distanceToSqr(attackTarget) < 16D && this.getAnimationTick() == 5) {
            attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            double attackmotionX = (Math.signum(this.getX() - attackTarget.getX()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;
            double attackmotionY = (Math.signum(this.getY() - attackTarget.getY() + 1) * 0.5D - attackTarget.getDeltaMovement().y) * 0.100000000372529 * 5;
            double attackmotionZ = (Math.signum(this.getZ() - attackTarget.getZ()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;

            attackTarget.setDeltaMovement(attackTarget.getDeltaMovement().add(attackmotionX, attackmotionY, attackmotionZ));
            // float angle = (float) (Math.atan2(attackTarget.getDeltaMovement().z, attackTarget.getDeltaMovement().x) * 180.0D / Math.PI) - 90.0F;
            // entity.moveForward = 0.5F;
            double d0 = this.getX() - attackTarget.getX();
            double d2 = this.getZ() - attackTarget.getZ();
            double d1 = this.getY() - 1 - attackTarget.getY();
            double d3 = Math.sqrt((float) (d0 * d0 + d2 * d2));
            float f = (float) (Mth.atan2(d2, d0) * (180D / Math.PI)) - 90.0F;
            float f1 = (float) (-(Mth.atan2(d1, d3) * (180D / Math.PI)));
            attackTarget.setXRot(updateRotation(attackTarget.getXRot(), f1, 30F));
            attackTarget.setYRot(updateRotation(attackTarget.getYRot(), f, 30F));
        }
        if (level.isClientSide) {
            tail_buffer.calculateChainSwingBuffer(40, 10, 2.5F, this);
        }
        if (this.isAgressive()) {
            ticksAgressive++;
        } else {
            ticksAgressive = 0;
        }
        if (ticksAgressive > 300 && this.isAgressive() && attackTarget == null && !level.isClientSide) {
            this.setAggressive(false);
            this.ticksAgressive = 0;
            this.setSinging(false);
        }

        if (this.isInWater() && !this.isSwimming()) {
            this.setSwimming(true);
        }
        if (!this.isInWater() && this.isSwimming()) {
            this.setSwimming(false);
        }
        LivingEntity target = getTarget();
        boolean pathOnHighGround = this.isPathOnHighGround() || !level.isClientSide && target != null && !target.isInWater();
        if (target == null || !target.isInWater() && !target.isInWater()) {
            if (pathOnHighGround && this.isInWater()) {
                jumpFromGround();
                doWaterSplashEffect();
            }
        }
        if ((this.isInWater() && !pathOnHighGround) && this.isLandNavigator) {
            switchNavigator(false);
        }
        if ((!this.isInWater() || pathOnHighGround) && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (target instanceof Player && ((Player) target).isCreative()) {
            this.setTarget(null);
            this.setAggressive(false);
        }
        if (target != null && !this.isAgressive()) {
            this.setAggressive(true);
        }
        boolean singing = isActuallySinging() && !this.isAgressive() && !this.isInWater() && onGround;
        if (singing && singProgress < 20.0F) {
            singProgress += 1F;
        } else if (!singing && singProgress > 0.0F) {
            singProgress -= 1F;
        }
        boolean swimming = isSwimming();
        if (swimming && swimProgress < 20.0F) {
            swimProgress += 1F;
        } else if (!swimming && swimProgress > 0.0F) {
            swimProgress -= 0.5F;
        }
        if (!level.isClientSide && !EntityGorgon.isStoneMob(this) && this.isActuallySinging()) {
            updateLure();
            checkForPrey();

        }
        if (!level.isClientSide && EntityGorgon.isStoneMob(this) && this.isSinging()) {
            this.setSinging(false);
        }
        if (isActuallySinging() && !this.isInWater()) {
            if (this.getRandom().nextInt(3) == 0) {
                yBodyRot = getYRot();
                if (this.level.isClientSide) {
                    float radius = -0.9F;
                    float angle = (0.01745329251F * this.yBodyRot) - 3F;
                    double extraX = radius * Mth.sin((float) (Math.PI + angle));
                    double extraY = 1.2F;
                    double extraZ = radius * Mth.cos(angle);
                    IceAndFire.PROXY.spawnParticle(EnumParticles.Siren_Music, this.getX() + extraX + this.random.nextFloat() - 0.5, this.getY() + extraY + this.random.nextFloat() - 0.5, this.getZ() + extraZ + this.random.nextFloat() - 0.5, 0, 0, 0);
                }
            }
        }
        if (this.isActuallySinging() && !this.isInWater() && this.tickCount % 200 == 0) {
            this.playSound(IafSoundRegistry.SIREN_SONG, 2, 1);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void updateLure() {
        if (this.tickCount % 20 == 0) {
            List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(50, 12, 50), SIREN_PREY);
            for (LivingEntity entity : entities) {
                if (!isWearingEarplugs(entity) && (!SirenProperties.isCharmed(entity) || SirenProperties.getSiren(entity) == null)) {
                    SirenProperties.setCharmedBy(entity, this);
                }
            }
        }
    }

public static boolean isWearingEarplugs(LivingEntity entity) {
        ItemStack helmet = entity.getItemBySlot(EquipmentSlot.HEAD);
        return helmet.getItem() == IafItemRegistry.EARPLUGS.get() || helmet != ItemStack.EMPTY && helmet.getItem().getDescriptionId().contains("earmuff");
    }

public void setSinging(boolean singing) {
        if (singCooldown > 0) {
            singing = false;
        }
        this.entityData.set(SINGING, singing);
        if (!level.isClientSide) {
            this.isSinging = singing;
            IceAndFire.sendMSGToAll(new MessageSirenSong(this.getId(), singing));
        }
    }

public boolean isSinging() {
        if (level.isClientSide) {
            return this.isSinging = this.entityData.get(SINGING).booleanValue();
        }
        return isSinging;
    }

public boolean isActuallySinging() {
        return isSinging() && !wantsToSing();
    }

public boolean wantsToSing() {
        return this.isSinging() && this.isInWater() && !this.isAgressive();
    }

public void triggerOtherSirens(LivingEntity aggressor) {
        List<Entity> entities = level.getEntities(this, this.getBoundingBox().inflate(12, 12, 12));
        for (Entity entity : entities) {
            if (entity instanceof EntitySiren) {
                ((EntitySiren) entity).setTarget(aggressor);
                ((EntitySiren) entity).setAggressive(true);
                ((EntitySiren) entity).setSinging(false);

            }
        }
    }

@Override
    public void addAdditionalSaveData(@NotNull CompoundTag tag) {
        super.addAdditionalSaveData(tag);
        tag.putInt("HairColor", this.getHairColor());
        tag.putBoolean("Aggressive", this.isAgressive());
        tag.putInt("SingingPose", this.getSingingPose());
        tag.putBoolean("Singing", this.isSinging());
        tag.putBoolean("Swimming", this.isSwimming());
        tag.putBoolean("Passive", this.isCharmed());

    }

@Override
    public void readAdditionalSaveData(@NotNull CompoundTag tag) {
        super.readAdditionalSaveData(tag);
        this.setHairColor(tag.getInt("HairColor"));
        this.setAggressive(tag.getBoolean("Aggressive"));
        this.setSingingPose(tag.getInt("SingingPose"));
        this.setSinging(tag.getBoolean("Singing"));
        this.setSwimming(tag.getBoolean("Swimming"));
        this.setCharmed(tag.getBoolean("Passive"));

    }

public static void tickCharmedEntity(LivingEntity entity) {
        EntitySiren siren = getSiren(entity);
        if (siren != null && siren.isActuallySinging()) {
            if (EntitySiren.isWearingEarplugs(entity) || getSingTime(entity) > IafConfig.sirenMaxSingTime) {
                clearCharmedStatus(entity);
                siren.singCooldown = IafConfig.sirenTimeBetweenSongs;
            } else {
                if (!siren.isAlive() || entity.distanceTo(siren) > EntitySiren.SEARCH_RANGE * 2 || entity instanceof Player && ((Player) entity).isCreative()) {
                    clearCharmedStatus(entity);
                    return;
                }
                if (entity.distanceTo(siren) < 5D) {
                    clearCharmedStatus(entity);
                    siren.singCooldown = IafConfig.sirenTimeBetweenSongs;
                    siren.setSinging(false);
                    siren.setTarget(entity);
                    siren.setAggressive(true);
                    siren.triggerOtherSirens(entity);
                    return;
                }
                CompoundTag sirenData = getOrCreateCharmData(entity);
                sirenData.putBoolean(SIREN_CHARMED, true);
                sirenData.putInt(SIREN_TIME, getSingTime(entity));
                updateCharmData(entity, sirenData);

                if (rand.nextInt(7) == 0) {
                    for (int i = 0; i < 5; i++) {
                        entity.level.addParticle(ParticleTypes.HEART,
                            entity.getX() + ((rand.nextDouble() - 0.5D) * 3),
                            entity.getY() + ((rand.nextDouble() - 0.5D) * 3),
                            entity.getZ() + ((rand.nextDouble() - 0.5D) * 3),
                            0, 0, 0);
                    }
                }
                if (entity.horizontalCollision) {
                    entity.setJumping(true);
                }
                double motionXAdd = (Math.signum(siren.getX() - entity.getX()) * 0.5D - entity.getDeltaMovement().x) * 0.100000000372529;
                double motionYAdd = (Math.signum(siren.getY() - entity.getY() + 1) * 0.5D - entity.getDeltaMovement().y) * 0.100000000372529;
                double motionZAdd = (Math.signum(siren.getZ() - entity.getZ()) * 0.5D - entity.getDeltaMovement().z) * 0.100000000372529;
                entity.setDeltaMovement(entity.getDeltaMovement().add(motionXAdd, motionYAdd, motionZAdd));
                if (entity.isPassenger()) {
                    entity.stopRiding();
                }
                if (!(entity instanceof Player)) {
                    double d0 = siren.getX() - entity.getX();
                    double d2 = siren.getZ() - entity.getZ();
                    double d1 = siren.getY() - 1 - entity.getY();
                    double d3 = Math.sqrt(d0 * d0 + d2 * d2);
                    float f = (float) (Mth.atan2(d2, d0) * (180D / Math.PI)) - 90.0F;
                    float f1 = (float) (-(Mth.atan2(d1, d3) * (180D / Math.PI)));
                    entity.setXRot(updateRotation(entity.getXRot(), f1, 30F));
                    entity.setYRot(updateRotation(entity.getYRot(), f, 30F));
                }
            }
        }
    }

public static void setCharmedBy(LivingEntity entity, LivingEntity charmedBy) {
        CompoundTag nbt = getOrCreateCharmData(entity);
        nbt.putInt(SIREN_ID, charmedBy.getId());
        nbt.putBoolean(SIREN_CHARMED, true);
        updateCharmData(entity, nbt);
    }

@Nullable
    public static EntitySiren getSiren(LivingEntity entity) {
        Entity siren = entity.level.getEntity(getCharmedBy(entity));
        if (siren instanceof EntitySiren) {
            return (EntitySiren) siren;
        }
        return null;
    }

private static int getSingTime(LivingEntity entity) {
        CompoundTag nbt = getOrCreateCharmData(entity);
        if (nbt.contains(SIREN_TIME)) {
            return nbt.getInt(SIREN_TIME);
        }
        return 0;
    }

private static int getCharmedBy(LivingEntity entity) {
        CompoundTag nbt = getOrCreateCharmData(entity);
        if (nbt.contains(SIREN_ID)) {
            return nbt.getInt(SIREN_ID);
        }
        return -1;
    }

private static void updateCharmData(LivingEntity entity, CompoundTag nbt) {
        CompoundTag entityData = CitadelEntityData.getOrCreateCitadelTag(entity);
        entityData.put(SIREN_DATA, nbt);
        CitadelEntityData.setCitadelTag(entity, entityData);
        if (!entity.level.isClientSide()) {
            Citadel.sendMSGToAll(new PropertiesMessage("CitadelPatreonConfig", entityData, entity.getId()));
        }
    }

public static boolean isCharmed(LivingEntity entity) {
        CompoundTag nbt = getOrCreateCharmData(entity);
        if (!nbt.contains(SIREN_CHARMED)) {
            nbt = createDefaultData();
            updateCharmData(entity, nbt);
        }
        return nbt.getBoolean(SIREN_CHARMED);
    }

private static void clearCharmedStatus(LivingEntity entity) {
        CompoundTag charmData = getOrCreateCharmData(entity);
        clearCharmedStatus(charmData);
        updateCharmData(entity, charmData);
    }

private static CompoundTag clearCharmedStatus(CompoundTag nbt) {
        nbt.putInt(SIREN_TIME, 0);
        nbt.putBoolean(SIREN_CHARMED, false);
        nbt.putInt(SIREN_ID, -1);
        return nbt;
    }

private static CompoundTag getOrCreateCharmData(LivingEntity entity) {
        return getOrCreateCharmData(CitadelEntityData.getCitadelTag(entity));
    }

private static CompoundTag getOrCreateCharmData(CompoundTag entityData) {
        if (entityData.contains(SIREN_DATA, 10)) {
            return (CompoundTag) entityData.get(SIREN_DATA);
        } else return createDefaultData();
    }

@SubscribeEvent
    public void onEntityUpdate(LivingEvent.LivingUpdateEvent event) {

        if (ChainProperties.hasChainData(event.getEntityLiving())) {
            ChainProperties.tickChain(event.getEntityLiving());
        }

        if (IafConfig.chickensLayRottenEggs && !event.getEntityLiving().level.isClientSide && isChicken(event.getEntityLiving()) && !event.getEntityLiving().isBaby() && event.getEntityLiving() instanceof Animal) {
            ChickenProperties.tickChicken(event.getEntityLiving());
        }

        if (FrozenProperties.isFrozen(event.getEntityLiving())) {
            FrozenProperties.tickFrozenEntity(event.getEntityLiving());

            if (!(event.getEntityLiving() instanceof Player && ((Player) event.getEntityLiving()).isCreative())) {
                event.getEntity().setDeltaMovement(event.getEntity().getDeltaMovement().multiply(0.25F, 1, 0.25F));
                if (!(event.getEntityLiving() instanceof EnderDragon) && !event.getEntityLiving().isOnGround()) {
                    event.getEntity().setDeltaMovement(event.getEntity().getDeltaMovement().add(0, -0.2, 0));
                }

            }
        }

        if (event.getEntityLiving() instanceof Player || event.getEntityLiving() instanceof AbstractVillager || event.getEntityLiving() instanceof IHearsSiren) {
            SirenProperties.tickCharmedEntity(event.getEntityLiving());
        }

        if (MiscProperties.getLoveTicks(event.getEntityLiving()) > 0) {
            MiscProperties.tickLove(event.getEntityLiving());
        }
        if (AiDebug.isEnabled() && event.getEntityLiving() instanceof Mob && AiDebug.contains((Mob) event.getEntityLiving())) {
            AiDebug.logData();
        }
    }
